1	/**
2	 * Unit tests for runner.js (D6c runner wrapper).
3	 *
4	 * Uses a fake HTTP server as the broker and fake executor scripts to test:
5	 *   1. Happy path: executor exits 0, result.json exists → broker receives result
6	 *   2. Non-zero exit: executor exits 1 → broker receives failed result + stderr tail
7	 *   3. Transport retry: broker fails first N attempts → runner retries and succeeds
8	 */
9	
10	import { describe, it, expect, beforeEach, afterEach } from "vitest";
11	import { mkdtempSync, writeFileSync, rmSync } from "node:fs";
12	import { tmpdir } from "node:os";
13	import { join } from "node:path";
14	import * as http from "node:http";
15	import { fileURLToPath } from "node:url";
16	import { httpPost, postWithRetry, runWrapper } from "../runner.js";
17	
18	const RUNNER_PATH = fileURLToPath(new URL("../runner.js", import.meta.url));
19	
20	// ── helpers ───────────────────────────────────────────────────────────────────
21	
22	function mkTemp(): string {
23	  return mkdtempSync(join(tmpdir(), "runner-test-"));
24	}
25	
26	function writeFakeExecutor(dir: string, opts: {
27	  exitCode?: number;
28	  result?: object;
29	  stderrMsg?: string;
30	}): string {
31	  const { exitCode = 0, result, stderrMsg } = opts;
32	  const resultPath = join(dir, "result.json");
33	  const lines: string[] = [];
34	  if (stderrMsg) {
35	    lines.push(`process.stderr.write(${JSON.stringify(stderrMsg + "\\n")});`);
36	  }
37	  if (result !== undefined) {
38	    lines.push(
39	      `import { writeFileSync } from 'node:fs';`,
40	      `writeFileSync(${JSON.stringify(resultPath)}, JSON.stringify(${JSON.stringify(result)}));`,
41	    );
42	  }
43	  lines.push(`process.exit(${exitCode});`);
44	  const scriptPath = join(dir, "fake-executor.mjs");
45	  writeFileSync(scriptPath, lines.join("\n"), "utf8");
46	  return scriptPath;
47	}
48	
49	interface ReceivedCall {
50	  body: unknown;
51	}
52	
53	function startFakeBroker(opts: {
54	  failFirst?: number;
55	  statusCode?: number;
56	}): Promise<{ url: string; calls: ReceivedCall[]; close: () => Promise<void> }> {
57	  const { failFirst = 0, statusCode = 204 } = opts;
58	  const calls: ReceivedCall[] = [];
59	  let callCount = 0;
60	
61	  return new Promise((resolve) => {
62	    const server = http.createServer((req, res) => {
63	      let raw = "";
64	      req.on("data", (chunk: Buffer) => { raw += chunk.toString(); });
65	      req.on("end", () => {
66	        callCount++;
67	        if (callCount <= failFirst) {
68	          res.writeHead(503);
69	          res.end("Service Unavailable");
70	          return;
71	        }
72	        try {
73	          calls.push({ body: JSON.parse(raw) });
74	        } catch {
75	          calls.push({ body: raw });
76	        }
77	        res.writeHead(statusCode);
78	        res.end();
79	      });
80	    });
81	
82	    server.listen(0, "127.0.0.1", () => {
83	      const addr = server.address() as { port: number };
84	      const url = `http://127.0.0.1:${addr.port}/callback`;
85	      resolve({
86	        url,
87	        calls,
88	        close: () => new Promise<void>((r) => server.close(() => r())),
89	      });
90	    });
91	  });
92	}
93	
94	// ── httpPost unit tests ───────────────────────────────────────────────────────
95	
96	describe("httpPost", () => {
97	  it("resolves on 2xx response", async () => {
98	    const broker = await startFakeBroker({});
99	    await expect(httpPost(broker.url, JSON.stringify({ test: 1 }))).resolves.toBeUndefined();
100	    expect(broker.calls).toHaveLength(1);
101	    await broker.close();
102	  });
103	
104	  it("rejects on non-2xx response", async () => {
105	    const broker = await startFakeBroker({ statusCode: 401 });
106	    await expect(httpPost(broker.url, "{}")).rejects.toThrow("HTTP 401");
107	    await broker.close();
108	  });
109	});
110	
111	// ── postWithRetry unit tests ──────────────────────────────────────────────────
112	
113	describe("postWithRetry", () => {
114	  it("succeeds on first attempt when broker is healthy", async () => {
115	    const broker = await startFakeBroker({});
116	    await postWithRetry(broker.url, "{}", 3, 10);
117	    expect(broker.calls).toHaveLength(1);
118	    await broker.close();
119	  });
120	
121	  it("retries and eventually succeeds after transient failures", async () => {
122	    const broker = await startFakeBroker({ failFirst: 2 });
123	    await postWithRetry(broker.url, JSON.stringify({ x: 1 }), 5, 10);
124	    expect(broker.calls).toHaveLength(1);
125	    expect((broker.calls[0].body as { x: number }).x).toBe(1);
126	    await broker.close();
127	  });
128	});
129	
130	// ── runWrapper integration tests ──────────────────────────────────────────────
131	
132	describe("runWrapper", () => {
133	  let tmpDir: string;
134	
135	  beforeEach(() => {
136	    tmpDir = mkTemp();
137	  });
138	
139	  afterEach(() => {
140	    rmSync(tmpDir, { recursive: true, force: true });
141	  });
142	
143	  it("happy path: posts valid result when executor exits 0", async () => {
144	    const expectedResult = { terminal_status: "in_review", pr_url: "https://github.com/org/repo/pull/1" };
145	    const executorBin = writeFakeExecutor(tmpDir, { exitCode: 0, result: expectedResult });
146	    const resultPath = join(tmpDir, "result.json");
147	    const broker = await startFakeBroker({});
148	
149	    await runWrapper({
150	      resultPath,
151	      callbackUrl: broker.url,
152	      handle: "handle-abc",
153	      nonce: "nonce-xyz",
154	      executorBin,
155	      maxAttempts: 3,
156	      baseDelayMs: 10,
157	      env: { ...process.env },
158	    });
159	
160	    expect(broker.calls).toHaveLength(1);
161	    const payload = broker.calls[0].body as { handle: string; nonce: string; result: typeof expectedResult };
162	    expect(payload.handle).toBe("handle-abc");
163	    expect(payload.nonce).toBe("nonce-xyz");
164	    expect(payload.result).toEqual(expectedResult);
165	
166	    await broker.close();
167	  });
168	
169	  it("non-zero exit: posts failed result with exit code", async () => {
170	    const stderrMsg = "Something went terribly wrong on this line";
171	    const executorBin = writeFakeExecutor(tmpDir, { exitCode: 1, stderrMsg });
172	    const resultPath = join(tmpDir, "result.json");
173	    const broker = await startFakeBroker({});
174	
175	    await runWrapper({
176	      resultPath,
177	      callbackUrl: broker.url,
178	      handle: "handle-fail",
179	      nonce: "nonce-fail",
180	      executorBin,
181	      maxAttempts: 3,
182	      baseDelayMs: 10,
183	      env: { ...process.env },
184	    });
185	
186	    expect(broker.calls).toHaveLength(1);
187	    const payload = broker.calls[0].body as {
188	      handle: string;
189	      nonce: string;
190	      result: { terminal_status: string; blocked_reason: string; blocked_suggestion?: string };
191	    };
192	    expect(payload.handle).toBe("handle-fail");
193	    expect(payload.result.terminal_status).toBe("failed");
194	    expect(payload.result.blocked_reason).toContain("exit 1");
195	    expect(payload.result.blocked_suggestion).toContain(stderrMsg);
196	
197	    await broker.close();
198	  });
199	
200	  it("transport retry: retries POST on transient broker failures", async () => {
201	    const expectedResult = { terminal_status: "in_review" };
202	    const executorBin = writeFakeExecutor(tmpDir, { exitCode: 0, result: expectedResult });
203	    const resultPath = join(tmpDir, "result.json");
204	    const broker = await startFakeBroker({ failFirst: 2 });
205	
206	    await runWrapper({
207	      resultPath,
208	      callbackUrl: broker.url,
209	      handle: "handle-retry",
210	      nonce: "nonce-retry",
211	      executorBin,
212	      maxAttempts: 5,
213	      baseDelayMs: 10,
214	      env: { ...process.env },
215	    });
216	
217	    expect(broker.calls).toHaveLength(1);
218	    const payload = broker.calls[0].body as { result: { terminal_status: string } };
219	    expect(payload.result.terminal_status).toBe("in_review");
220	
221	    await broker.close();
222	  });
