  if (result !== undefined) {
    lines.push(
      `import { writeFileSync } from 'node:fs';`,
      `writeFileSync(${JSON.stringify(resultPath)}, JSON.stringify(${JSON.stringify(result)}));`,
    );
  }
  lines.push(`process.exit(${exitCode});`);
  const scriptPath = join(dir, "fake-executor.mjs");
  writeFileSync(scriptPath, lines.join("\n"), "utf8");
  return scriptPath;
}

interface ReceivedCall {
  body: unknown;
}

function startFakeBroker(opts: {
  failFirst?: number;
  statusCode?: number;
}): Promise<{ url: string; calls: ReceivedCall[]; close: () => Promise<void> }> {
  const { failFirst = 0, statusCode = 204 } = opts;
  const calls: ReceivedCall[] = [];
  let callCount = 0;

  return new Promise((resolve) => {
    const server = http.createServer((req, res) => {
      let raw = "";
      req.on("data", (chunk: Buffer) => { raw += chunk.toString(); });
      req.on("end", () => {
        callCount++;
        if (callCount <= failFirst) {
          res.writeHead(503);
          res.end("Service Unavailable");
          return;
        }
        try {
          calls.push({ body: JSON.parse(raw) });
        } catch {
          calls.push({ body: raw });
        }
        res.writeHead(statusCode);
        res.end();
      });
    });

    server.listen(0, "127.0.0.1", () => {
      const addr = server.address() as { port: number };
      const url = `http://127.0.0.1:${addr.port}/callback`;
      resolve({
        url,
        calls,
        close: () => new Promise<void>((r) => server.close(() => r())),
      });
    });
  });
}

// ── httpPost unit tests ───────────────────────────────────────────────────────

describe("httpPost", () => {
  it("resolves on 2xx response", async () => {
    const broker = await startFakeBroker({});
    await expect(httpPost(broker.url, JSON.stringify({ test: 1 }))).resolves.toBeUndefined();
    expect(broker.calls).toHaveLength(1);
    await broker.close();
  });

  it("rejects on non-2xx response", async () => {
    const broker = await startFakeBroker({ statusCode: 401 });
    await expect(httpPost(broker.url, "{}")).rejects.toThrow("HTTP 401");
    await broker.close();
  });
});

// ── postWithRetry unit tests ──────────────────────────────────────────────────

describe("postWithRetry", () => {
  it("succeeds on first attempt when broker is healthy", async () => {
    const broker = await startFakeBroker({});
    await postWithRetry(broker.url, "{}", 3, 10);
    expect(broker.calls).toHaveLength(1);
    await broker.close();
  });

  it("retries and eventually succeeds after transient failures", async () => {
    const broker = await startFakeBroker({ failFirst: 2 });
    await postWithRetry(broker.url, JSON.stringify({ x: 1 }), 5, 10);
    expect(broker.calls).toHaveLength(1);
    expect((broker.calls[0].body as { x: number }).x).toBe(1);
    await broker.close();
  });
});

// ── runWrapper integration tests ──────────────────────────────────────────────

describe("runWrapper", () => {
  let tmpDir: string;

  beforeEach(() => {
    tmpDir = mkTemp();
  });

  afterEach(() => {
    rmSync(tmpDir, { recursive: true, force: true });
  });

  it("happy path: posts valid result when executor exits 0", async () => {
    const expectedResult = { terminal_status: "in_review", pr_url: "https://github.com/org/repo/pull/1" };
    const executorBin = writeFakeExecutor(tmpDir, { exitCode: 0, result: expectedResult });
    const resultPath = join(tmpDir, "result.json");
    const broker = await startFakeBroker({});

    await runWrapper({
      resultPath,
      callbackUrl: broker.url,
      handle: "handle-abc",
      nonce: "nonce-xyz",
      executorBin,
      maxAttempts: 3,
      baseDelayMs: 10,
      env: { ...process.env },
    });

    expect(broker.calls).toHaveLength(1);
    const payload = broker.calls[0].body as { handle: string; nonce: string; result: typeof expectedResult };
    expect(payload.handle).toBe("handle-abc");
    expect(payload.nonce).toBe("nonce-xyz");
    expect(payload.result).toEqual(expectedResult);

    await broker.close();
  });

  it("non-zero exit: posts failed result with exit code", async () => {
    const stderrMsg = "Something went terribly wrong on this line";
    const executorBin = writeFakeExecutor(tmpDir, { exitCode: 1, stderrMsg });
    const resultPath = join(tmpDir, "result.json");
    const broker = await startFakeBroker({});

    await runWrapper({
      resultPath,
      callbackUrl: broker.url,
      handle: "handle-fail",
      nonce: "nonce-fail",
      executorBin,
      maxAttempts: 3,
      baseDelayMs: 10,
      env: { ...process.env },
    });

    expect(broker.calls).toHaveLength(1);
    const payload = broker.calls[0].body as {
      handle: string;
      nonce: string;
      result: { terminal_status: string; blocked_reason: string; blocked_suggestion?: string };
    };
    expect(payload.handle).toBe("handle-fail");
    expect(payload.result.terminal_status).toBe("failed");
    expect(payload.result.blocked_reason).toContain("exit 1");
    expect(payload.result.blocked_suggestion).toContain(stderrMsg);

    await broker.close();
  });

  it("transport retry: retries POST on transient broker failures", async () => {
    const expectedResult = { terminal_status: "in_review" };
    const executorBin = writeFakeExecutor(tmpDir, { exitCode: 0, result: expectedResult });
    const resultPath = join(tmpDir, "result.json");
    const broker = await startFakeBroker({ failFirst: 2 });

    await runWrapper({
      resultPath,
      callbackUrl: broker.url,
      handle: "handle-retry",
      nonce: "nonce-retry",
      executorBin,
      maxAttempts: 5,
      baseDelayMs: 10,
      env: { ...process.env },
    });

    expect(broker.calls).toHaveLength(1);
    const payload = broker.calls[0].body as { result: { terminal_status: string } };
    expect(payload.result.terminal_status).toBe("in_review");

    await broker.close();
  });

  it("non-zero exit with no stderr: posts failed result without blocked_suggestion", async () => {
    const executorBin = writeFakeExecutor(tmpDir, { exitCode: 2 });
    const resultPath = join(tmpDir, "result.json");
    const broker = await startFakeBroker({});

    await runWrapper({
      resultPath,
      callbackUrl: broker.url,
      handle: "handle-silent-fail",
      nonce: "nonce-silent-fail",
      executorBin,
      maxAttempts: 3,
      baseDelayMs: 10,
      env: { ...process.env },
    });

    expect(broker.calls).toHaveLength(1);
    const payload = broker.calls[0].body as {
      result: { terminal_status: string; blocked_reason: string; blocked_suggestion?: string };
    };
    expect(payload.result.terminal_status).toBe("failed");
    expect(payload.result.blocked_reason).toContain("exit 2");
    expect(payload.result.blocked_suggestion).toBeUndefined();

    await broker.close();
  });
});

